<script setup lang="ts">
import type { ApiSuccess } from '~/types/api'
import { apiErrorMessage } from '~/utils/api-error'

definePageMeta({ layout: 'dashboard', middleware: 'auth' })
useHead({ title: 'Modèles de contrats — IFICS' })

type Template = { id: string; contractType: string; name: string; content: string; active: boolean; isDefault: boolean; version: number; updatedAt: string }
type BuiltIn = { contractType: string; name: string; content: string }
type Payload = { templates: Template[]; builtIns: BuiltIn[] }
const { data, error, refresh } = await useFetch<ApiSuccess<Payload>>('/api/settings/contracts')
const templates = computed(() => data.value?.data.templates ?? [])
const initializing = ref(false)
const saving = ref(false)
const selectedId = ref('')
const message = ref('')
const errorMessage = ref('')
const form = reactive({ contractType: 'CDI', name: '', content: '', active: true, isDefault: false })
const labels: Record<string, string> = { CDI: 'CDI', CDD: 'CDD', STAGE: 'Stage', ALTERNANCE: 'Alternance', APPRENTISSAGE: 'Apprentissage', PROFESSIONNALISATION: 'Professionnalisation', VOLONTARIAT: 'Volontariat', OTHER: 'Autre' }

function edit(item: Template) { selectedId.value = item.id; Object.assign(form, { contractType: item.contractType, name: item.name, content: item.content, active: item.active, isDefault: item.isDefault }); message.value = ''; errorMessage.value = '' }
function createNew() { selectedId.value = ''; Object.assign(form, { contractType: 'CDI', name: '', content: '', active: true, isDefault: false }); message.value = ''; errorMessage.value = '' }
async function initialize() { if (initializing.value) return; initializing.value = true; errorMessage.value = ''; try { const response = await $fetch<ApiSuccess<{ created: number }>>('/api/settings/contracts/initialize', { method: 'POST' }); await refresh(); message.value = response.data.created ? `${response.data.created} ${response.data.created === 1 ? 'modèle IFICS initialisé' : 'modèles IFICS initialisés'}.` : 'Les modèles IFICS sont déjà initialisés.' } catch (error) { errorMessage.value = apiErrorMessage(error, 'Les modèles n’ont pas pu être initialisés.') } finally { initializing.value = false } }
async function save() { if (saving.value) return; saving.value = true; errorMessage.value = ''; try { await $fetch('/api/settings/contracts/save', { method: 'POST', body: { id: selectedId.value || undefined, ...form } }); await refresh(); message.value = 'Modèle enregistré.'; createNew() } catch (error) { errorMessage.value = apiErrorMessage(error, 'Le modèle n’a pas pu être enregistré.') } finally { saving.value = false } }
</script>
<template><div><div class="page-head"><div><p class="eyebrow">Paramètres</p><h1>Modèles de contrats RH</h1><p>Versionnez les modèles utilisés pour préparer les documents RH. Chaque document généré devra conserver son propre instantané.</p></div><div class="actions"><NuxtLink class="btn btn-secondary" to="/dashboard/settings">Retour</NuxtLink><button class="btn btn-secondary" type="button" :disabled="initializing" @click="initialize">{{ initializing ? 'Initialisation…' : 'Initialiser les modèles IFICS' }}</button></div></div><div v-if="error" class="alert alert-error">Vous n’avez pas accès aux modèles de contrats.</div><template v-else><div v-if="message" class="alert alert-success" style="margin-bottom:18px">{{ message }}</div><div v-if="errorMessage" class="alert alert-error" style="margin-bottom:18px">{{ errorMessage }}</div><div class="contracts-layout"><section class="card card-pad"><div class="actions title-actions"><h2>Modèles</h2><button class="btn btn-secondary" type="button" @click="createNew">Nouveau</button></div><div v-if="!templates.length" class="empty-state">Aucun modèle. Initialisez les modèles IFICS ou créez-en un.</div><button v-for="item in templates" :key="item.id" class="template-row" type="button" :class="{ active: selectedId === item.id }" @click="edit(item)"><span><strong>{{ item.name }}</strong><small>{{ labels[item.contractType] || item.contractType }} · v{{ item.version }}</small></span><span class="badge">{{ item.active ? (item.isDefault ? 'Défaut' : 'Actif') : 'Inactif' }}</span></button></section><form class="card card-pad" @submit.prevent="save"><h2>{{ selectedId ? 'Modifier le modèle' : 'Nouveau modèle' }}</h2><div class="field"><label for="contract-type">Type *</label><select id="contract-type" v-model="form.contractType" class="select"><option v-for="(label,key) in labels" :key="key" :value="key">{{ label }}</option></select></div><div class="field"><label for="contract-name">Nom *</label><input id="contract-name" v-model="form.name" class="input" maxlength="180" required></div><div class="field"><label for="contract-content">Contenu *</label><textarea id="contract-content" v-model="form.content" class="textarea code" rows="24" maxlength="100000" required /></div><div class="checks"><label><input v-model="form.active" type="checkbox"> Actif</label><label><input v-model="form.isDefault" type="checkbox"> Modèle par défaut pour ce type</label></div><p class="help">Variables disponibles dans les modèles intégrés : <code v-text="'{{association.legalName}}'" />, <code v-text="'{{employee.fullName}}'" />, <code v-text="'{{position.title}}'" />, <code v-text="'{{contract.startDate}}'" /> et autres champs documentés dans le modèle.</p><button class="btn btn-primary" type="submit" :disabled="saving || !form.name.trim() || !form.content.trim()">{{ saving ? 'Enregistrement…' : 'Enregistrer' }}</button></form></div></template></div></template>
<style scoped>.contracts-layout{display:grid;grid-template-columns:minmax(260px,.8fr) minmax(0,1.5fr);gap:18px}.title-actions{justify-content:space-between}.title-actions h2{margin:0}.template-row{width:100%;display:flex;justify-content:space-between;align-items:center;gap:12px;text-align:left;border:1px solid var(--ifics-border);background:#fff;border-radius:10px;padding:12px;margin-top:10px;cursor:pointer}.template-row.active{outline:2px solid #2d7050}.template-row span:first-child{display:flex;flex-direction:column;gap:3px}.template-row small{color:var(--ifics-muted)}.code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace}.checks{display:flex;gap:20px;flex-wrap:wrap;margin:14px 0}.checks label{display:flex;gap:7px;align-items:center}@media(max-width:900px){.contracts-layout{grid-template-columns:1fr}}</style>
